#define main carryfree_exact_main
#include "lp2_red8_carryfree_continuous_sft.cpp"
#undef main
struct Model{
 const Lex& lex; static constexpr int B=30; array<double,B*B*B> tri{}; array<double,B*B> bi{}; array<double,B> mono{};array<double,B*B*B> logtri{};
 explicit Model(const Lex& l):lex(l){for(auto& [w,n]:l.counts){double weight=sqrt(double(n));int a=29,b=29;for(size_t i=0;i<=w.size();i++){int c=i<w.size()?ord(w[i]):29;tri[(a*B+b)*B+c]+=weight;bi[b*B+c]+=weight;mono[c]+=weight;a=b;b=c;}}double N=accumulate(mono.begin(),mono.end(),0.0);for(int a=0;a<B;a++)for(int b=0;b<B;b++){double tb=0,bb=0;for(int c=0;c<B;c++){tb+=tri[(a*B+b)*B+c];bb+=bi[b*B+c];}for(int c=0;c<B;c++){double uni=(mono[c]+1)/(N+B);double p2=(bi[b*B+c]+30*uni)/(bb+30);double p3=(tri[(a*B+b)*B+c]+30*p2)/(tb+30);logtri[(a*B+b)*B+c]=log(p3);}}}
 double score(const string& w,double bonus)const{int a=29,b=29;double v=0;for(size_t i=0;i<=w.size();i++){int c=i<w.size()?ord(w[i]):29;v+=logtri[(a*B+b)*B+c];a=b;b=c;}auto it=lex.counts.find(w);if(it!=lex.counts.end())v+=bonus+0.25*log(it->second+1.0);return v;}
};
struct Anneal{
 const Model& m;Schedule sc;mt19937 rng;array<int,Q> pi,inv;vector<string> dec;vector<double> scores;double sum=0,bonus;int oov=0;uint64_t iters=0;double best=-1e99;int bestOov=100;array<int,Q> bestPi{};vector<string> bestDec;
 Anneal(const Model& m,const vector<string>& w,const array<int,8>& k,int st,uint64_t h,uint32_t seed,double bonus):m(m),sc(w,k,st,h),rng(seed),bonus(bonus){}
 int bad(const string& w,int i)const{int n=0;for(int j=0;j<(int)w.size();j++)n+=sc.spec[i][j].k>=0&&w[j]=='0';return n;}
 int invalid=0,bestBad=100;
 void start(){iota(pi.begin(),pi.end(),0);shuffle(pi.begin(),pi.end(),rng);for(int p=0;p<Q;p++)inv[pi[p]]=p;dec.clear();scores.clear();sum=0;oov=0;invalid=0;for(int i=0;i<(int)sc.spec.size();i++){string w;for(auto [c,k]:sc.spec[i])w+=k<0?'0':S[inv[mod(pi[c]-k)]];int n=bad(w,i);double v=m.score(w,bonus)-10*n;dec.push_back(w);scores.push_back(v);sum+=v;oov+=!m.lex.all.count(w);invalid+=n;}}
 void save(){if(invalid<bestBad||(invalid==bestBad&&(oov<bestOov||(oov==bestOov&&sum>best)))){bestBad=invalid;bestOov=oov;best=sum;bestPi=pi;for(int& x:bestPi)x=mod(x-pi[0]);bestDec=dec;}}
 bool step(double t){int a=rng()%Q,b=rng()%Q;if(a==b)return false;int va=pi[a],vb=pi[b];swap(pi[a],pi[b]);swap(inv[va],inv[vb]);array<string,64> changed;array<double,64> ns{};uint64_t change=0;double delta=0;int od=0,bd=0;for(int i=0;i<(int)sc.spec.size();i++){auto& spec=sc.spec[i];string w=dec[i];bool diff=false;for(int j=0;j<(int)spec.size();j++){auto [c,k]=spec[j];if(k<0)continue;if(c==a||c==b||w[j]==S[a]||w[j]==S[b]){char p=S[inv[mod(pi[c]-k)]];diff|=p!=w[j];w[j]=p;}}if(diff){change|=1ull<<i;int n=bad(w,i);double z=m.score(w,bonus)-10*n;delta+=z-scores[i];ns[i]=z;od+=int(!m.lex.all.count(w))-int(!m.lex.all.count(dec[i]));bd+=n-bad(dec[i],i);changed[i]=move(w);}}
  double u=(rng()+0.5)/4294967296.0;if(delta>=0||log(u)<delta/t){sum+=delta;oov+=od;invalid+=bd;while(change){int i=__builtin_ctzll(change);change&=change-1;dec[i]=move(changed[i]);scores[i]=ns[i];}save();return true;}swap(pi[a],pi[b]);swap(inv[va],inv[vb]);return false;}
 void run(int seconds){auto end=Clock::now()+chrono::seconds(seconds);while(Clock::now()<end){start();save();for(int i=0;i<60000;i++){double t=8*pow(0.05,i/59999.0);step(t);iters++;if(bestBad==0&&bestOov<=3)return;if((i&1023)==0&&Clock::now()>=end)return;}}}
};
int main(int argc,char** argv){string path=argv[1],mode=argv[2];int sec=stoi(argv[3]),start=argc>4?stoi(argv[4]):0,end=argc>5?stoi(argv[5]):128;double bonus=argc>6?stod(argv[6]):5;Lex l(path);Model m(l);if(mode=="control"){for(int ki=start;ki<end;ki++){auto p=plant(ki?141:67,ki,ki?0x6cf32b:0x59ba31);Anneal a(m,p.train,KEYS[ki],p.start,p.history,0xa9537u+ki,bonus);double truth=0;for(auto& w:p.truth)truth+=m.score(w,bonus);a.run(sec);cout<<"control="<<ki<<" bestBad="<<a.bestBad<<" bestOOV="<<a.bestOov<<" score="<<a.best<<" truthScore="<<truth<<" iterations="<<a.iters<<" pi="<<label(a.bestPi)<<" recovered="<<(a.bestPi==p.pi)<<" decoded="<<join(a.bestDec)<<"\n"<<flush;}return 0;}auto w=words(ORIGINAL);for(int id=start;id<end;id++){int ki=id/64,h=id%64/8,st=id%8;Anneal a(m,w,KEYS[ki],st,h,0x9ba37u+id,bonus);a.run(sec);cout<<"id="<<id<<" bestBad="<<a.bestBad<<" bestOOV="<<a.bestOov<<" score="<<a.best<<" iterations="<<a.iters<<" pi="<<label(a.bestPi)<<" decoded="<<join(a.bestDec)<<"\n"<<flush;}}
